<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Invoices</title><link rel="stylesheet" href="<?=base_url('styles.css')?>"><style>body{background:#090b0d;color:#eee}.wrap{max-width:1100px;margin:auto;padding:30px}.top{display:flex;justify-content:space-between}.table{width:100%;border-collapse:collapse;margin-top:22px;background:#111416}.table th,.table td{padding:14px;border-bottom:1px solid #292929;text-align:left}.btn{padding:9px 13px;border:1px solid #444;border-radius:9px;color:#ead5ad;text-decoration:none}@media(max-width:700px){.table{font-size:12px}.top{display:block}}</style></head><body><div class="wrap"><div class="top"><div><div style="color:#c8a66e;letter-spacing:.15em;font-size:11px">CLIENT PORTAL</div><h1 style="font:500 38px Georgia,serif">My Invoices</h1></div><a class="btn" href="<?=site_url('dashboard')?>">← Dashboard</a></div><table class="table"><tr><th>Invoice</th><th>Date</th><th>Matter</th><th>Amount</th><th>Status</th><th></th></tr><?php if(!$invoices):?><tr><td colspan="6">No invoices have been issued to your account.</td></tr><?php endif;?><?php foreach($invoices as $i):?><tr><td><b><?=esc($i['invoice_no'])?></b></td><td><?=date('d M Y',strtotime($i['invoice_date']))?></td><td><?=esc($i['case_reference']?:'—')?></td><td>₹ <?=number_format($i['total'],2)?></td><td><?=esc($i['payment_status'])?></td><td><a class="btn" href="<?=site_url('my-invoices/'.$i['id'])?>">View</a></td></tr><?php endforeach;?></table></div></body></html>
